    10→export function StaffDashboardPage() {
    11→  const { user, token } = useAuth();
    12→  const { campusSlug } = useParams();
    13→  const routeCampus = getCampusBySlug(campusSlug);
    14→  const campus = routeCampus ?? getCampusByCode(user?.campusId ?? null);
    15→
    16→  const staffRole =
    17→    user?.role && user.role in roleConfigs ? (user.role as keyof typeof roleConfigs) : "DEPARTMENT_HEAD";
    18→  const roleConfig = roleConfigs[staffRole];
    19→  const workspace = useStaffWorkspace(roleConfig);
    20→
    21→  // Profile update state
    22→  const [showProfileModal, setShowProfileModal] = useState(false);
    23→  const [profileForm, setProfileForm] = useState({ email: user?.email ?? "" });
    24→  const [profileSubmitting, setProfileSubmitting] = useState(false);
    25→  const [profileFeedback, setProfileFeedback] = useState<{ ok: boolean; msg: string } | null>(null);
    26→
    27→  async function handleUpdateProfile(e: React.FormEvent<HTMLFormElement>) {
    28→    e.preventDefault();
    29→    if (!token) return;
    30→    if (!profileForm.email || !profileForm.email.trim()) {
    31→      setProfileFeedback({ ok: false, msg: "Email is required." });
    32→      return;
    33→    }
    34→    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(profileForm.email)) {
    35→      setProfileFeedback({ ok: false, msg: "Please enter a valid email address." });
    36→      return;
    37→    }
    38→    setProfileSubmitting(true);
    39→    setProfileFeedback(null);
    40→    try {
    41→      await api.updateMyProfile(token, { email: profileForm.email.trim() });
    42→      setProfileFeedback({ ok: true, msg: "Email updated successfully." });
    43→      setTimeout(() => setShowProfileModal(false), 1500);
    44→    } catch (e) {
    45→      setProfileFeedback({ ok: false, msg: e instanceof Error ? e.message : "Failed to update email." });
    46→    } finally {
    47→      setProfileSubmitting(false);
    48→    }
    49→  }
    50→
    51→  return (
    52→    <StaffWorkbenchTailwind
    53→      campus={campus}
    54→      roleConfig={roleConfig}
    55→      staffRole={staffRole}
    56→      {...workspace}
    57→      showProfileModal={showProfileModal}
    58→      setShowProfileModal={setShowProfileModal}
    59→      profileForm={profileForm}
    60→      setProfileForm={setProfileForm}
    61→      profileSubmitting={profileSubmitting}
    62→      profileFeedback={profileFeedback}
    63→      handleUpdateProfile={handleUpdateProfile}
    64→    />
    65→  );
    66→}
