    39→function looksLikeDevProxyCouldNotReachApi(status: number, body: string): boolean {
    40→  if (status === 502 || status === 503 || status === 504) {
    41→    return true;
    42→  }
    43→  const b = body.toLowerCase();
    44→  return (
    45→    status === 500 &&
    46→    (b.includes("econnrefused") ||
    47→      b.includes("proxy error") ||
    48→      b.includes("aggregateerror") ||
    49→      b.includes("socket hang up") ||
    50→      b.includes("connect econnrefused") ||
    51→      b.trim().length === 0)
    52→  );
    53→}
    54→
    55→export function toApiUrl(path?: string | null) {
    56→  if (!path) {
    57→    return null;
    58→  }
    59→  if (path.startsWith("http://") || path.startsWith("https://")) {
    60→    return path;
    61→  }
    62→  const origin = API_BASE_URL.replace(/\/api\/v1$/, "");
    63→  return `${origin}${path.startsWith("/") ? path : `/${path}`}`;
    64→}
    65→
    66→async function request<T>(
    67→  path: string,
    68→  options: RequestInit = {},
    69→  token?: string
    70→): Promise<T> {
    71→  const url = `${API_BASE_URL}${path}`;
    72→  let response: Response;
    73→  try {
    74→    response = await fetch(url, {
    75→      ...options,
    76→      headers: {
    77→        "Content-Type": "application/json",
    78→        ...(token ? { Authorization: `Bearer ${token}` } : {}),
    79→        ...(options.headers ?? {})
    80→      }
    81→    });
    82→  } catch (err) {
    83→    const detail = err instanceof Error ? err.message : "Network error";
    84→    void detail;
    85→    throw new Error(`Unable to connect to the UGClear system. ${BACKEND_DOWN_HINT}`);
    86→  }
    87→
    88→  const text = await response.text();
    89→
    90→  if (!response.ok) {
    91→    if (response.status === 401 && token) {
    92→      notifySessionInvalid();
    93→    }
    94→    if (looksLikeDevProxyCouldNotReachApi(response.status, text)) {
    95→      throw new Error(
    96→        `Unable to connect to the UGClear system. ${BACKEND_DOWN_HINT}`
    97→      );
    98→    }
    99→
   100→    let message = "Request failed";
   101→
   102→    try {
   103→      const errorBody = (text ? JSON.parse(text) : {}) as { message?: string; error?: string };
   104→      message = errorBody.message?.trim() || message;
   105→      if (!errorBody.message?.trim()) {
   106→        if (response.status === 401) {
   107→          message = "Your session expired or credentials were rejected. Please sign in again.";
   108→        } else if (response.status === 403) {
   109→          message =
   110→            errorBody.error === "FORBIDDEN"
   111→              ? "Access denied. If you just signed in, try again or contact the administrator."
   112→              : "Access denied.";
   113→        } else if (response.status === 500) {
   114→          message = `Something went wrong on our end. ${BACKEND_DOWN_HINT}`;
   115→        }
   116→      }
   117→    } catch {
   118→      message = response.statusText || text.trim().slice(0, 200) || message;
   119→      if (response.status === 401) {
   120→        message = "Authentication required. Please sign in again.";
   121→      } else if (response.status === 403) {
   122→        message = "Access denied.";
   123→      } else if (response.status === 500) {
   124→        message = `Something went wrong on our end. ${BACKEND_DOWN_HINT}`;
   125→      }
   126→    }
   127→
   128→    throw new Error(message);
   129→  }
   130→
   131→  if (response.status === 204 || !text) {
   132→    return undefined as T;
   133→  }
   134→
   135→  return JSON.parse(text) as T;
   136→}
