   180→        List<ClearanceCheck> checks = principal.getUser().getRole() == UserRole.SYSTEM_ADMIN
   181→                ? clearanceCheckRepository.findAll()
   182→                : clearanceCheckRepository.findByCampusIdAndCheckCodeAndStatusNot(
