   271→    private void refreshCheckStatusFromLiabilities(String clearanceRequestId, ClearanceCheckCode checkCode, String reviewerId) {
   272→        List<Liability> liabilities = liabilityRepository.findByClearanceRequestIdAndDepartmentCheckCode(clearanceRequestId, checkCode);
   273→        boolean hasOutstandingPayment = liabilities.stream()
   274→                .anyMatch(liability -> liability.isPaymentRequired()
   275→                        && liability.getStatus() != LiabilityStatus.PAID
   276→                        && liability.getStatus() != LiabilityStatus.CLEARED
   277→                        && liability.getStatus() != LiabilityStatus.WAIVED);
   278→        boolean hasOutstandingNonPayment = liabilities.stream()
   279→                .anyMatch(liability -> !liability.isPaymentRequired()
   280→                        && liability.getStatus() != LiabilityStatus.CLEARED
   281→                        && liability.getStatus() != LiabilityStatus.WAIVED);
   282→
   283→        if (hasOutstandingPayment) {
   284→            updateCheckStatus(
   285→                    clearanceRequestId,
   286→                    checkCode,
   287→                    ClearanceCheckStatus.AWAITING_FINANCE,
   288→                    reviewerId,
   289→                    "Outstanding payment must be completed and verified by finance.");
   290→            return;
   291→        }
   292→
   293→        if (!hasOutstandingNonPayment) {
   294→            updateCheckStatus(
   295→                    clearanceRequestId,
   296→                    checkCode,
   297→                    ClearanceCheckStatus.IN_REVIEW,
   298→                    reviewerId,
   299→                    "All recorded issues are resolved. Final departmental approval is required.");
   300→        }
   301→    }
