   303→    private void validateReviewTransition(ClearanceCheck check, ClearanceCheckStatus requestedStatus) {
   304→        if (requestedStatus != ClearanceCheckStatus.CLEARED) {
   305→            return;
   306→        }
   307→
   308→        List<Liability> liabilities = liabilityRepository.findByClearanceRequestIdAndDepartmentCheckCode(
   309→                check.getClearanceRequestId(),
   310→                check.getCheckCode());
   311→
   312→        boolean hasOutstandingPayment = liabilities.stream()
   313→                .anyMatch(liability -> liability.isPaymentRequired()
   314→                        && liability.getStatus() != LiabilityStatus.PAID
   315→                        && liability.getStatus() != LiabilityStatus.CLEARED
   316→                        && liability.getStatus() != LiabilityStatus.WAIVED);
   317→        if (hasOutstandingPayment) {
   318→            throw new IllegalArgumentException("Finance must verify payment before this department can clear the student");
   319→        }
   320→
   321→        boolean hasOutstandingNonPayment = liabilities.stream()
   322→                .anyMatch(liability -> !liability.isPaymentRequired()
   323→                        && liability.getStatus() != LiabilityStatus.CLEARED
   324→                        && liability.getStatus() != LiabilityStatus.WAIVED);
   325→        if (hasOutstandingNonPayment) {
   326→            throw new IllegalArgumentException("Outstanding department issues must be resolved before clearance");
   327→        }
   328→
   329→        boolean requiresFinanceConfirmation = liabilities.stream().anyMatch(Liability::isPaymentRequired);
   330→        if (requiresFinanceConfirmation && check.getStatus() != ClearanceCheckStatus.PAID_PENDING_DEPARTMENT_APPROVAL) {
   331→            throw new IllegalArgumentException("This check can only be cleared after finance sends back a verified receipt");
   332→        }
   333→    }
