   408→    public ClearanceStatisticsResponse getStatistics(String campusId) {
   409→        List<ClearanceRequest> allRequests = campusId == null 
   410→            ? clearanceRequestRepository.findAll()
   411→            : clearanceRequestRepository.findByCampusId(campusId);
   412→        
   413→        long totalRequests = allRequests.size();
   414→        long clearedRequests = allRequests.stream()
   415→            .filter(r -> r.getStatus() == ClearanceRequestStatus.CLEARED)
   416→            .count();
   417→        
   418→        double clearancePercentage = totalRequests == 0 ? 0 : (clearedRequests * 100.0) / totalRequests;
   419→        
   420→        // Find most common bottleneck
   421→        Map<ClearanceCheckCode, Long> bottleneckCounts = new java.util.HashMap<>();
   422→        List<ClearanceCheck> allChecks = campusId == null
   423→            ? clearanceCheckRepository.findAll()
   424→            : clearanceCheckRepository.findByCampusId(campusId);
   425→        
   426→        allChecks.stream()
   427→            .filter(c -> c.getStatus() != ClearanceCheckStatus.CLEARED && c.getStatus() != ClearanceCheckStatus.IN_REVIEW)
   428→            .forEach(c -> bottleneckCounts.merge(c.getCheckCode(), 1L, Long::sum));
   429→        
   430→        ClearanceCheckCode mostCommonBottleneck = bottleneckCounts.entrySet().stream()
   431→            .max(java.util.Map.Entry.comparingByValue())
   432→            .map(java.util.Map.Entry::getKey)
   433→            .orElse(ClearanceCheckCode.LIBRARY);
   434→        
   435→        int bottleneckCount = bottleneckCounts.getOrDefault(mostCommonBottleneck, 0L).intValue();
   436→        
   437→        int pendingCount = (int) allChecks.stream()
   438→            .filter(c -> c.getStatus() == ClearanceCheckStatus.PENDING)
   439→            .count();
   440→        
   441→        int inReviewCount = (int) allChecks.stream()
   442→            .filter(c -> c.getStatus() == ClearanceCheckStatus.IN_REVIEW)
   443→            .count();
   444→        
   445→        int flaggedCount = (int) allChecks.stream()
   446→            .filter(c -> c.getStatus() == ClearanceCheckStatus.FLAGGED)
   447→            .count();
   448→        
   449→        return new ClearanceStatisticsResponse(
   450→            totalRequests,
   451→            clearedRequests,
   452→            clearancePercentage,
   453→            mostCommonBottleneck,
   454→            bottleneckCount,
   455→            pendingCount,
   456→            inReviewCount,
   457→            flaggedCount
   458→        );
   459→    }
