   476→                List<ClearanceCheck> checks = clearanceCheckRepository.findByClearanceRequestId(request.getId());
   477→                
   478→                long clearedChecks = checks.stream()
   479→                    .filter(c -> c.getStatus() == ClearanceCheckStatus.CLEARED)
   480→                    .count();
   481→                
   482→                int progressPercentage = checks.isEmpty() ? 0 : (int) ((clearedChecks * 100) / checks.size());
   483→                
   484→                List<ClearanceCheckResponse> checkResponses = checks.stream()
   485→                    .map(this::toCheckResponse)
   486→                    .toList();
   487→                
   488→                boolean hasCertificate = qrCertificateRepository.findByClearanceRequestId(request.getId())
   489→                    .isPresent();
   490→                
   491→                return new StudentClearanceOverviewResponse(
   492→                    request.getId(),
   493→                    request.getRequestNumber(),
   494→                    studentIdentity,
   495→                    request.getStatus(),
   496→                    request.getSubmittedAt(),
   497→                    progressPercentage,
   498→                    checkResponses,
   499→                    hasCertificate
   500→                );
   501→            })
   502→            .filter(Objects::nonNull)
   503→            .toList();
