   190→async function generateQrBase64(data: {
   191→  studentId: string;
   192→  fullName: string;
   193→  program: string | null;
   194→  campus: string;
   195→  clearedDate: string;
   196→  requestNumber: string;
   197→  hash: string;
   198→}): Promise<string> {
   199→  const text = [
   200→    "UGClear — University of Gondar",
   201→    "OFFICIAL CLEARANCE CERTIFICATE",
   202→    "",
   203→    `Student: ${data.fullName}`,
   204→    `ID: ${data.studentId}`,
   205→    `Program: ${data.program ?? "—"}`,
   206→    `Campus: ${data.campus}`,
   207→    `Cleared: ${data.clearedDate}`,
   208→    `Request: ${data.requestNumber}`,
   209→    "",
   210→    `Verify Hash: ${data.hash}`,
   211→  ].join("\n");
   212→
   213→  try {
   214→    const dataUrl = await QRCode.toDataURL(text, {
   215→      width: 400,
   216→      margin: 2,
   217→      color: { dark: "#001e40", light: "#ffffff" },
   218→      errorCorrectionLevel: "M",
   219→    });
   220→    return dataUrl.replace("data:image/png;base64,", "");
   221→  } catch {
   222→    return "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==";
   223→  }
   224→}
