   300→// ── Token helpers ─────────────────────────────────────────────────────────────
   301→
   302→function makeToken(userId: string): string {
   303→  return "mock_" + btoa(JSON.stringify({ userId, iat: Date.now() }));
   304→}
   305→
   306→function userFromToken(token: string, db: Db): DbUser | null {
   307→  try {
   308→    if (!token.startsWith("mock_")) return null;
   309→    const { userId } = JSON.parse(atob(token.slice(5))) as { userId: string };
   310→    return db.users.find((u) => u.id === userId) ?? null;
   311→  } catch {
   312→    return null;
   313→  }
   314→}
   315→
   316→function requireAuth(token: string | null, db: Db): DbUser {
   317→  if (!token) throw { status: 401, message: "Authentication required." };
   318→  const u = userFromToken(token, db);
   319→  if (!u) throw { status: 401, message: "Session expired. Please sign in again." };
   320→  return u;
   321→}
   322→
   323→function studentForUser(user: DbUser, db: Db): DbStudent | null {
   324→  if (user.role !== "STUDENT" || !user.studentId) return null;
   325→  return db.students.find((s) => s.studentId === user.studentId) ?? null;
   326→}
