   328→// ── Helpers ──────────────────────────────────────────────────────────────────
   329→
   330→function computeRequestStatus(checks: DbCheck[], _liabilities: DbLiability[]): string {
   331→  if (checks.every((c) => c.status === "CLEARED")) return "CLEARED";
   332→  if (checks.some((c) => c.status === "FLAGGED" || c.status === "FAILED")) return "FLAGGED";
   333→  if (checks.some((c) => c.status === "AWAITING_FINANCE")) return "AWAITING_FINANCE";
   334→  if (checks.some((c) => c.status === "IN_REVIEW")) return "IN_REVIEW";
   335→  return "PENDING";
   336→}
   337→
   338→function buildStatusPayload(req: DbRequest, student: DbStudent, db: Db) {
   339→  const checks = db.checks.filter((c) => c.clearanceRequestId === req.id);
   340→  const liabilities = db.liabilities.filter((l) => l.clearanceRequestId === req.id);
   341→  const payments = db.payments.filter((p) => p.clearanceRequestId === req.id);
   342→  const certificate = db.certificates.find((c) => c.clearanceRequestId === req.id) ?? null;
   343→  return {
   344→    request: {
   345→      id: req.id, requestNumber: req.requestNumber, studentId: req.studentId,
   346→      campusId: req.campusId, semester: req.semester, academicYearLabel: req.academicYearLabel,
   347→      requestType: req.requestType, status: req.status, submittedAt: req.submittedAt,
   348→    },
   349→    student: {
   350→      studentId: student.studentId, firstName: student.firstName, middleName: student.middleName,
   351→      lastName: student.lastName, gender: student.gender, phone: student.phone, email: student.email,
   352→      campusId: student.campusId, academicDepartmentId: student.academicDepartmentId,
   353→      program: student.program, academicYear: student.academicYear, graduationYear: student.graduationYear,
   354→      hasProfileImage: false, profileImageUrl: null, hasIdCardImage: false, idCardImageUrl: null,
   355→    },
   356→    checks, liabilities, payments, certificate,
   357→  };
   358→}
