   362→function handleLogin(body: { username: string; password: string; expectedCampusId?: string }, db: Db) {
   363→  const user = db.users.find((u) => u.username === body.username && u.password === body.password);
   364→  if (!user) throw { status: 401, message: "Invalid username or password." };
   365→  if (!user.active) throw { status: 403, message: "Account is deactivated." };
   366→  if (body.expectedCampusId && user.campusId && user.campusId !== body.expectedCampusId && user.role !== "SYSTEM_ADMIN") {
   367→    throw { status: 403, message: "CAMPUS_MISMATCH" };
   368→  }
   369→  const token = makeToken(user.id);
   370→  return { accessToken: token, tokenType: "Bearer", userId: user.id, username: user.username, role: user.role, campusId: user.campusId, mustChangePassword: user.mustChangePassword };
   371→}
