   394→// Student endpoints
   395→function handleListStudentRequests(token: string | null, db: Db) {
   396→  const user = requireAuth(token, db);
   397→  const student = studentForUser(user, db);
   398→  if (!student) throw { status: 403, message: "No student profile found." };
   399→  return db.requests.filter((r) => r.studentId === student.studentId).sort((a, b) => b.submittedAt.localeCompare(a.submittedAt));
   400→}
   401→
   402→function handleCreateStudentRequest(token: string | null, body: { semester: string; academicYearLabel: string; requestType: string }, db: Db) {
   403→  const user = requireAuth(token, db);
   404→  const student = studentForUser(user, db);
   405→  if (!student) throw { status: 403, message: "No student profile found." };
   406→  const existing = db.requests.filter((r) => r.studentId === student.studentId && r.status !== "CLOSED" && r.status !== "CLEARED");
   407→  if (existing.length > 0) throw { status: 400, message: "You already have an active clearance request." };
   408→
   409→  const reqId = uid();
   410→  const reqNum = "CLR-" + String(Math.floor(Math.random() * 90000) + 10000);
   411→  const now = isoNow();
   412→
   413→  // Cross-check: find ALL unpaid liabilities for this student recorded by any staff
   414→  const unpaidLiabilities = db.liabilities.filter(
   415→    (l) => l.studentId === student.studentId && !["PAID", "CLEARED", "WAIVED"].includes(l.status)
   416→  );
   417→  // Which office check-codes have open debts
   418→  const flaggedCodes = new Set(unpaidLiabilities.map((l) => l.departmentCheckCode));
   419→
   420→  const request: DbRequest = {
   421→    id: reqId, requestNumber: reqNum, studentId: student.studentId,
   422→    campusId: student.campusId, semester: body.semester,
   423→    academicYearLabel: body.academicYearLabel, requestType: body.requestType,
   424→    status: flaggedCodes.size > 0 ? "FLAGGED" : "PENDING",
   425→    submittedAt: now
   426→  };
   427→  db.requests.push(request);
   428→
   429→  // Create checks — immediately flag offices that have recorded unpaid liabilities
   430→  for (const code of CHECK_CODES) {
   431→    if (flaggedCodes.has(code)) {
   432→      const offenceItems = unpaidLiabilities
   433→        .filter((l) => l.departmentCheckCode === code)
   434→        .map((l) => l.itemName + " (" + l.amount.toFixed(2) + " ETB)")
   435→        .join(", ");
   436→      db.checks.push({
   437→        id: uid(), clearanceRequestId: reqId, checkCode: code,
   438→        status: "FLAGGED",
   439→        reviewedBy: null, reviewedAt: null,
   440→        comment: "Unpaid liabilities on record: " + offenceItems + ". Resolve before clearance can be approved."
   441→      });
   442→    } else {
   443→      db.checks.push({ id: uid(), clearanceRequestId: reqId, checkCode: code, status: "PENDING", reviewedBy: null, reviewedAt: null, comment: null });
   444→    }
   445→  }
   446→
   447→  writeDb(db);
   448→  return request;
   449→}
