   451→function handleGetStudentStatus(token: string | null, requestId: string, db: Db) {
   452→  const user = requireAuth(token, db);
   453→  const student = studentForUser(user, db);
   454→  if (!student) throw { status: 403, message: "No student profile found." };
   455→  const req = db.requests.find((r) => r.id === requestId && r.studentId === student.studentId);
   456→  if (!req) throw { status: 404, message: "Clearance request not found." };
   457→  return buildStatusPayload(req, student, db);
